-- Gold Query
SELECT T1.Phone FROM schools AS T1 INNER JOIN satscores AS T2 ON T1.CDSCode = T2.cds ORDER BY CAST(T2.NumGE1500 AS REAL) / T2.NumTstTakr DESC, T1.cdscode NULLS LAST, T2.cds NULLS LAST LIMIT 3;

